package com.vibeguard.samples.shipping; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import java.util.*; import java.util.concurrent.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/labels") public class LabelController {private final Map<String,Label> labels=new ConcurrentHashMap<>();@PostMapping public ResponseEntity<Label> create(@Valid @RequestBody Request request){String tracking=UUID.randomUUID().toString();Label label=new Label(request.orderId(),request.carrier(),tracking,"PDF","ACTIVE");labels.put(tracking,label);return ResponseEntity.status(201).body(label);}@GetMapping("/{tracking}") public ResponseEntity<Label> get(@PathVariable String tracking){return Optional.ofNullable(labels.get(tracking)).map(ResponseEntity::ok).orElseGet(()->ResponseEntity.notFound().build());}@PostMapping("/{tracking}/void") public ResponseEntity<Label> voidLabel(@PathVariable String tracking){Label label=labels.get(tracking);if(label==null)return ResponseEntity.notFound().build();Label voided=new Label(label.orderId(),label.carrier(),tracking,label.pdf(),"VOID");labels.put(tracking,voided);return ResponseEntity.ok(voided);}record Request(@NotBlank String orderId,@NotBlank String carrier){}record Label(String orderId,String carrier,String tracking,String pdf,String status){} }
